package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.port.*; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.ai.problem.adapter.SafeSvgSanitizer; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class ProblemDiagramRenderer implements ProblemDiagramRendererPort { private final SafeSvgSanitizer sanitizer; public ProblemDiagramRenderer(SafeSvgSanitizer sanitizer){this.sanitizer=sanitizer;} public RenderedDiagram render(DiagramSpecV1 s,DiagramRenderContext c){int w=s.viewport().width(),h=s.viewport().height();String body="<rect x=\"0\" y=\"0\" width=\""+w+"\" height=\""+h+"\" fill=\"#FFFFFF\"/>";if(s instanceof NumberLineDiagramSpecV1 x)body+=new NumberLineSvgRenderer().render(x,c.values());else if(s instanceof CoordinateGraphDiagramSpecV1 x)body+=new CoordinateGraphSvgRenderer().render(x,c.values());else if(s instanceof PlaneGeometryDiagramSpecV1 x)body+=new PlaneGeometrySvgRenderer().render(x);else if(s instanceof SolidGeometryDiagramSpecV1 x)body+=new SolidGeometrySvgRenderer().render(x);else if(s instanceof DataTableDiagramSpecV1 x)body+=new DataTableSvgRenderer().render(x,c.values());String svg=sanitizer.sanitize(DeterministicSvgWriter.empty(w,h,body));try{return new RenderedDiagram(s.assetKey(),svg,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(svg.getBytes(StandardCharsets.UTF_8))),w,h,ProblemRendererVersion.CURRENT);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
